"""Bearer JWT authentication for inbound A2A JSON-RPC requests."""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, Optional

import jwt
import structlog
from a2a.auth.user import User

from rasa.core.a2a_server.config import (
    _SYMMETRIC_JWT_ALGORITHMS,
    A2AAuthConfig,
    A2AJwtAuthConfig,
)
from rasa.core.constants import BEARER_TOKEN_PREFIX
from rasa.shared.exceptions import RasaException
from rasa.shared.utils.io import resolve_environment_variables

structlogger = structlog.get_logger()

WWW_AUTHENTICATE_BEARER = "Bearer"

A2A_UNAUTHORIZED_RESPONSE_BODY: dict[str, str] = {"error": "Unauthorized"}


def a2a_bearer_unauthorized_response_headers() -> dict[str, str]:
    """Return HTTP headers for a failed bearer auth check (RFC 6750)."""
    return {"WWW-Authenticate": WWW_AUTHENTICATE_BEARER}


class A2AAuthenticatedUser(User):
    """A2A user representing a validated orchestrator JWT."""

    def __init__(self, jwt_payload: Dict[str, Any]) -> None:
        self._jwt_payload = jwt_payload

    @property
    def is_authenticated(self) -> bool:
        return True

    @property
    def user_name(self) -> str:
        for claim in ("sub", "preferred_username", "client_id"):
            value = self._jwt_payload.get(claim)
            if value:
                return str(value)
        return "orchestrator"


class A2ABearerAuthValidator:
    """Validate ``Authorization: Bearer <jwt>`` for configured A2A server auth."""

    def __init__(self, auth_config: A2AAuthConfig) -> None:
        if auth_config.jwt is None:
            raise ValueError("Bearer auth requires a 'jwt' configuration block.")
        self._jwt_config = auth_config.jwt
        self._verification_key = self._load_verification_key(self._jwt_config)

    @staticmethod
    def _load_verification_key(jwt_config: A2AJwtAuthConfig) -> str:
        if jwt_config.algorithm in _SYMMETRIC_JWT_ALGORITHMS:
            if not jwt_config.secret:
                raise RasaException(
                    f"JWT algorithm '{jwt_config.algorithm}' requires a configured "
                    "'secret' value."
                )
            resolved_secret = resolve_environment_variables(jwt_config.secret)
            if resolved_secret == jwt_config.secret and "${" in jwt_config.secret:
                raise RasaException(
                    "The provided JWT secret environment variable is not set."
                )

            if not isinstance(resolved_secret, str) or not resolved_secret:
                raise RasaException(
                    f"JWT algorithm '{jwt_config.algorithm}' requires a configured "
                    "'secret' value."
                )
            return resolved_secret

        if not jwt_config.public_key_path:
            raise RasaException(
                f"JWT algorithm '{jwt_config.algorithm}' requires "
                "'public_key_path' to be configured."
            )
        path = Path(jwt_config.public_key_path)
        try:
            return path.read_text(encoding="utf-8")
        except OSError as exc:
            raise RasaException(
                f"Could not read JWT public key from '{path}': {exc}"
            ) from exc

    def validate_authorization_header(
        self, authorization: Optional[str]
    ) -> Optional[Dict[str, Any]]:
        """Return decoded JWT claims when the bearer token is valid.

        Args:
            authorization: Raw ``Authorization`` header value.

        Returns:
            Decoded JWT payload, or ``None`` when the header is missing, malformed,
            or the token fails verification.
        """
        if not authorization:
            structlogger.debug("a2a_server.auth.missing_bearer_token")
            return None

        scheme, _, token = authorization.partition(" ")
        if scheme.lower() != BEARER_TOKEN_PREFIX.strip().lower():
            structlogger.debug("a2a_server.auth.missing_bearer_token")
            return None

        token = token.strip()
        if not token:
            structlogger.debug("a2a_server.auth.empty_bearer_token")
            return None

        decode_options: Dict[str, Any] = {}
        if self._jwt_config.issuer is None:
            decode_options["verify_iss"] = False
        if self._jwt_config.audience is None:
            decode_options["verify_aud"] = False

        try:
            return jwt.decode(
                token,
                self._verification_key,
                algorithms=[self._jwt_config.algorithm],
                issuer=self._jwt_config.issuer,
                audience=self._jwt_config.audience,
                options=decode_options,
            )
        except jwt.InvalidTokenError as exc:
            structlogger.debug(
                "a2a_server.auth.invalid_bearer_token",
                error_type=type(exc).__name__,
            )
            return None
